"""Real pose correspondence for clipped sleeves, including new cuff vertices."""
import argparse,json
from pathlib import Path
from playwright.sync_api import sync_playwright
parser=argparse.ArgumentParser();parser.add_argument('--url',default='http://127.0.0.1:4255/');parser.add_argument('--out',required=True);args=parser.parse_args();out=Path(args.out);out.mkdir(parents=True,exist_ok=True)
with sync_playwright() as p:
 b=p.chromium.launch(channel='msedge',headless=True);pg=b.new_page(viewport={'width':1200,'height':900});errors=[];pg.on('pageerror',lambda e:errors.append(str(e)));pg.goto(args.url);pg.wait_for_selector('body[data-ready=true]',timeout=60000);pg.locator('#view').click()
 for posture in ['caller','controller','standing','seated']:
  pg.locator('#posture').select_option(posture)
  for phase in [0,.25,.5,.75]:pg.evaluate('phase=>illustratedPreview.seek(phase*.75)',phase);pg.locator('#scene').screenshot(path=str(out/f'{posture}-{phase}.png'))
 report=pg.evaluate('''()=>{const h=illustratedPreview.hybrid,results=[];for(const a of h.actors.filter(a=>a.role==='caller'||a.role==='controller'||a.role==='rower'&&[2,18].includes(a.id))){const pairs=a.skin.geometry.userData.garmentPairs;let maxGap=0;for(let step=0;step<17;step++){h.render(step/17,step/17,{teamId:'tum-nup-2'});const g=a.skin.geometry,bones=a.master.skeleton.boneMatrices;function packedPoint(attribute,packed,index){const x=attribute.getX(index),y=attribute.getY(index),z=attribute.getZ(index),ids=attribute.getW(index),weights=[packed[0]%4096,Math.floor(packed[0]/4096),packed[1]%4096,Math.floor(packed[1]/4096)],total=weights.reduce((a,b)=>a+b),out=a.group.position.clone().set(0,0,0);for(let k=0;k<4;k++){const off=(Math.floor(ids/64**k)%64)*16;out.x+=(bones[off]*x+bones[off+4]*y+bones[off+8]*z+bones[off+12])*weights[k]/total;out.y+=(bones[off+1]*x+bones[off+5]*y+bones[off+9]*z+bones[off+13])*weights[k]/total;out.z+=(bones[off+2]*x+bones[off+6]*y+bones[off+10]*z+bones[off+14])*weights[k]/total;}return out;}for(const [i,source]of pairs){const reference=a.group.position.clone().set(0,0,0);for(const [k,amount]of source)reference.addScaledVector(a.skin.getVertexPosition(k,a.group.position.clone()),amount);let cloth=a.skin.getVertexPosition(i,a.group.position.clone());if(g.attributes.cuffSourceA.getW(i)>=0){const w=g.attributes.cuffWeights,one=packedPoint(g.attributes.cuffSourceA,[w.getX(i),w.getY(i)],i),two=packedPoint(g.attributes.cuffSourceB,[w.getZ(i),w.getW(i)],i);cloth=one.lerp(two,g.attributes.shirtMix.getX(i));}maxGap=Math.max(maxGap,cloth.distanceTo(reference));}}results.push({id:a.id,role:a.role,posture:a.posture,clothVertices:pairs.length,intersections:pairs.filter(p=>p[1].length>1).length,maxPosedBarycentricGapM:maxGap});}return results;}''')
 assert all(r['clothVertices']>0 and r['intersections']>0 and r['maxPosedBarycentricGapM']<.006 for r in report),report;assert not errors,errors
 (out/'check.json').write_text(json.dumps({'url':args.url,'garmentFit':report,'posesPerActor':17,'correspondence':'original vertices or equivalent of actual packed shader endpoint skinning; direct role renders captured','errors':errors},indent=2),encoding='utf8');print(json.dumps(report));b.close()
